uname -r; cat /sys/kernel/realtime /sys/devices/system/cpu/online; printf "BLE=%s\n" "${BLE_VERSION-unset}"; command -v perf; zcat /proc/config.gz | grep -E "CONFIG_(PERF_EVENTS|FTRACE|FTRACE_SYSCALLS|FUNCTION_TRACER|TRACING|EVENT_TRACING|KPROBE_EVENTS|UPROBE_EVENTS|ARM_PMU|HW_PERF_EVENTS|KALLSYMS|FRAME_POINTER)"; ls -ld /sys/kernel/tracing /sys/kernel/debug/tracing; cat /proc/sys/kernel/perf_event_paranoid; ls /sys/bus/event_source/devices; ps | grep -E "[c]yclictest|[r]tload|[p]erf"; ls /tmp/rt-audit-tools; cat /proc/uptime
